// What the setup installs (tables generated by tools/vg_payload.py into gen/payload_table.c; the bytes are
// gen/payload.bin, included as the symbol vg_payload).
#pragma once
#include <stdint.h>

typedef struct {
    uint32_t off, size;
} vg_blob_t;

typedef struct {
    const char *path;     // resource path, e.g. generated/decls/...
    uint32_t off, size;   // its bytes in vg_payload (copy entries: none, taken from the player's game)
    int copy;             // a stock resource another catalog needs too: added where missing, never replaced
    const char *type, *name;  // index entry of a new resource
    uint8_t tail[10];     // its last 10 index bytes (byte 9, the data file, is set at install time)
} vg_file_t;

typedef struct {
    const char *key, *value;  // UTF-8
} vg_kv_t;

typedef struct {
    const char *stem;  // strings/<stem>.lang
    int first, count;  // its strings in VG_KV
} vg_lang_t;

typedef struct {
    int pct;              // screen scale
    vg_blob_t side, icon; // PNGs of the setup window
} vg_ui_t;

extern const unsigned char vg_payload[];
extern const char VG_VERSION[];
extern const vg_file_t VG_FILES[];
extern const int VG_NFILES;
extern const int VG_NEW_CATALOGS[4];
extern const vg_kv_t VG_KV[];
extern const vg_lang_t VG_LANGS[];
extern const int VG_NLANGS;
extern const vg_blob_t VG_DINPUT8, VG_MODULE;
extern const vg_ui_t VG_UI[5];
